    'ENT_' || LEFT(MD5('NPDES_ID' || '|' || (NULLIF(UPPER(REGEXP_REPLACE(TO_VARCHAR("NPDES_ID"), '[^0-9A-Za-z]', '')), ''))), 16) as spine_entity_id  -- joins LIBRARY_META."CONNECT".ENTITY_GOLDEN.ENTITY_ID

